  const step = workflow.jobs.verify.steps[0];
  assert.equal(step.name, 'Require passing unit and package checks');
  assert.match(step.run, /test "\$UNIT_RESULT" = success && test "\$PACKAGE_RESULT" = success/);
  for (const result of ['failure', 'cancelled', 'skipped']) {
    const c = context('pull_request'); c.needs.package.result = result;
    assert.ok(allowed(step.if, c, {success: false}));
    assert.equal(evaluate(step.env.PACKAGE_RESULT, c).coerceString(), result);
    for (const later of workflow.jobs.verify.steps.slice(1)) assert.equal(allowed(later.if, c, {success: false}), false);
  }
});

